#include "ui/bottom/BottomDock.hpp"
#include <QComboBox>
#include <QHBoxLayout>
#include <QLabel>
#include <QPushButton>
namespace Skink::Ui::Bottom { BottomDock::BottomDock(QWidget* parent):QWidget(parent){setObjectName("bottomBar");setFixedHeight(72);auto* l=new QHBoxLayout(this);l->setContentsMargins(18,10,18,12);l->setSpacing(12);auto* dot=new QLabel(this);dot->setObjectName("recordDot");dot->setFixedSize(14,14);l->addWidget(dot);auto* recording=new QLabel("GRABANDO",this);recording->setObjectName("bottomStrong");l->addWidget(recording);l->addWidget(new QLabel("00:00:00",this));l->addStretch();auto* duration=new QComboBox(this);duration->addItem("30 seg",30);duration->addItem("1 min",60);duration->addItem("3 min",180);duration->addItem("5 min",300);duration->setCurrentIndex(2);l->addWidget(duration);auto* preview=new QPushButton("VISTA PREVIA",this);auto* stop=new QPushButton("DETENER",this);auto* save=new QPushButton("GUARDAR PSD",this);for(auto* b:{preview,stop,save}){b->setObjectName("bottomButton");b->setFixedHeight(38);l->addWidget(b);}l->addStretch();auto* minus=new QPushButton("-",this);auto* zoom=new QLabel("100%",this);auto* plus=new QPushButton("+",this);for(auto* b:{minus,plus})b->setObjectName("zoomButton");l->addWidget(minus);l->addWidget(zoom);l->addWidget(plus);auto* center=new QPushButton("C   CENTRAR",this);center->setObjectName("bottomButton");center->setFixedHeight(38);l->addWidget(center);connect(minus,&QPushButton::clicked,this,&BottomDock::zoomOutRequested);connect(plus,&QPushButton::clicked,this,&BottomDock::zoomInRequested);connect(center,&QPushButton::clicked,this,&BottomDock::resetViewRequested);connect(preview,&QPushButton::clicked,this,&BottomDock::previewRequested);connect(stop,&QPushButton::clicked,this,&BottomDock::stopRequested);connect(save,&QPushButton::clicked,this,&BottomDock::savePsdRequested);connect(duration,&QComboBox::currentIndexChanged,this,[this,duration](int){emit processDurationChanged(duration->currentData().toInt());});} }
